validationRule.formulaExpression:
OR(
OR(
    AND(
        ISBLANK({!Dept}),
        ISBLANK({!productCategoryRepeater.AllItems[$EachItem].DepartmentName.topValue})
    ),
    AND(
        {!Dept} = {!productCategoryRepeater.AllItems[$EachItem].DepartmentName.topValue},
        NOT(ISBLANK({!productCategoryRepeater.AllItems[$EachItem].DepartmentName.middleValue}))
    )
),
OR(
    AND(
        ISBLANK({!Dept2}),
        ISBLANK({!productCategoryRepeater.AllItems[$EachItem].DepartmentName.topValue})
    ),
    AND(
        {!Dept2} = {!productCategoryRepeater.AllItems[$EachItem].DepartmentName.topValue},
        NOT(ISBLANK({!productCategoryRepeater.AllItems[$EachItem].DepartmentName.middleValue}))
    )
)
)
